// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ERC20, CoolerFactory} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    CoolerFactory factory;
    MockERC20 token;

    function setUp() public {
        c = new Cooler(); // kept verbatim; actual cooler comes from the factory
        factory = new CoolerFactory();
        token = new MockERC20();
    }

    function testFuzz_property(uint256 amountA, uint256 amountB, uint256 interest, uint256 ltc, uint256 duration, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amountA != amountB);
        amountA = bound(amountA, 1, type(uint256).max / 1e18);
        amountB = bound(amountB, 1, type(uint256).max / 1e18);
        ltc = bound(ltc, 1, type(uint256).max / 1e18);

        vm.prank(actor);
        address coolerAddr = factory.generateCooler(token, token);
        c = Cooler(coolerAddr);

        vm.prank(actor);
        uint256 idA = c.requestLoan(amountA, interest, ltc, duration);
        vm.prank(actor);
        uint256 idB = c.requestLoan(amountB, interest, ltc, duration);

        assertTrue(
            idA != idB &&
            c.getRequest(idA).amount == amountA &&
            c.getRequest(idB).amount == amountB &&
            c.getRequest(idA).active &&
            c.getRequest(idB).active
        );
    }
}

contract MockERC20 is ERC20 {
    constructor() ERC20("Mock", "MK", 18) {}

    function transfer(address, uint256) public override returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) public override returns (bool) {
        return true;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}
